const int SMB2_NEGOTIATE_SIGNING_REQUIRED = 2;

const int SMB2_TYPE_DIRECTORY = 1;

const int SMB2_TYPE_FILE = 0;

const int SMB2_TYPE_LINK = 2;

/// This creates a new smb2fh based on fileid. Free it with smb2_close_async()
final class smb2_context extends ffi.Opaque {}

final class smb2_libversion extends ffi.Struct {
  @ffi.Uint8()
  external int major_version;

  @ffi.Uint8()
  external int minor_version;

  @ffi.Uint8()
  external int patch_version;

  static ffi.Pointer<smb2_libversion> $allocate(
    ffi.Allocator $allocator, {
    required int major_version,
    required int minor_version,
    required int patch_version,
  }) => $allocator<smb2_libversion>()
    ..ref.major_version = major_version
    ..ref.minor_version = minor_version
    ..ref.patch_version = patch_version;
}

/// Set which version of SMB to negotiate. Default is to let the server pick the
/// version.
enum smb2_negotiate_version {
  SMB2_VERSION_ANY(0),
  SMB2_VERSION_ANY2(2),
  SMB2_VERSION_ANY3(3),
  SMB2_VERSION_0202(514),
  SMB2_VERSION_0210(528),
  SMB2_VERSION_0300(768),
  SMB2_VERSION_0302(770),
  SMB2_VERSION_0311(785);

  final int value;
  const smb2_negotiate_version(this.value);

  static smb2_negotiate_version fromValue(int value) => switch (value) {
    0 => SMB2_VERSION_ANY,
    2 => SMB2_VERSION_ANY2,
    3 => SMB2_VERSION_ANY3,
    514 => SMB2_VERSION_0202,
    528 => SMB2_VERSION_0210,
    768 => SMB2_VERSION_0300,
    770 => SMB2_VERSION_0302,
    785 => SMB2_VERSION_0311,
    _ => throw ArgumentError(
      'Unknown value for smb2_negotiate_version: $value',
    ),
  };
}

